<script>
(() => { const tabs=[...document.querySelectorAll('.variant-tab')], fields=[...document.querySelectorAll('[data-message]')], preview=document.getElementById('preview-bubble'), count=document.getElementById('char-count'); if(!fields.length)return; let selected=0; const refresh=()=>{preview.textContent=fields[selected].value.replace(/\{\{Name\}\}/g,'Nguyễn An');count.textContent=fields[selected].value.length}; tabs.forEach(tab=>tab.addEventListener('click',()=>{selected=Number(tab.dataset.variant);tabs.forEach(t=>t.classList.toggle('active',t===tab));fields.forEach((f,i)=>f.hidden=i!==selected);refresh()})); fields.forEach(f=>f.addEventListener('input',refresh)); const active=document.getElementById('active-field');document.getElementById('activate-button').addEventListener('click',()=>{active.value=active.value==='1'?'0':'1';document.getElementById('template-form').requestSubmit()}); refresh(); })();
</script></body></html>
